question.answer:
package main

import "fmt"

func status(book map[string]int, brand string) string {
	head, ok := book[brand]
	if !ok {
		return "unregistered"
	}
	if head == 0 {
		return "registered, no stock"
	}
	return fmt.Sprintf("registered, %d head", head)
}

func register(book map[string]int, brand string) {
	if _, ok := book[brand]; !ok {
		book[brand] = 0
	}
}

