question.answer:
package main

import (
	"fmt"
	"slices"
)

func tally(buyers []string) map[string]int {
	tickets := make(map[string]int)
	for _, name := range buyers {
		tickets[name]++
	}
	return tickets
}

func holders(tickets map[string]int) []string {
	var names []string
	for name := range tickets {
		names = append(names, name)
	}
	slices.Sort(names)
	return names
}

func notice(tickets map[string]int) []string {
	var lines []string
	for _, name := range holders(tickets) {
		lines = append(lines, fmt.Sprintf("%s x%d", name, tickets[name]))
	}
	return lines
}

testcode.text:
t := map[string]int{"maia": 1, "cole": 3, "rangi": 2, "ana": 1, "tui": 5, "hemi": 2}
fmt.Println(holders(t))
for _, line := range notice(t) {
	fmt.Println(line)
}

t := tally([]string{"Zoe", "adam", "Bob", "adam"})
fmt.Println(holders(t), holders(nil), len(notice(nil)))
for _, line := range notice(t) {
	fmt.Println(line)
}
